package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Sets the settings the form sets: a setting that carries a figure (the clerk limit, floor, terms, late percent,
 *  each grade's own terms, cap) is recorded from its from-date (the sheet's today when none is given), replacing a
 *  value recorded from that date and keeping the others; the policy date and period numbering from are set; a permission matrix entry
 *  (key perm-<action>) and the grace days are recorded undated. */
public class ApplySettings {
    public void apply(@Val SettingsInput input, @Val Sheet sheet, SheetRepository repository) {
        for (SettingsInput.Change change : input.changes()) {
            if (change.dated()) {
                sheet.record(change.key(), change.from() != null ? change.from() : sheet.getToday(), change.value());
            } else if (change.key().startsWith("perm-") || Sheet.GRACE_DAYS.equals(change.key())) {
                sheet.record(change.key(), null, change.value());
            } else if ("policy-date".equals(change.key())) {
                sheet.setPolicyDate(change.value() == null ? null : LocalDate.parse(change.value()));
            } else if ("period-numbering-from".equals(change.key())) {
                sheet.setPeriodNumberingFrom(change.value() == null ? null : LocalDate.parse(change.value()));
            }
        }
        repository.saveAndFlush(sheet);
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.List;

/** A validated settings form: the settings it sets, in the order they are recorded — the clerk limit, the floor, the
 *  terms, the late percent, the policy date, the period numbering from, the terms of grades A, B and C, the cap, the proof threshold, the
 *  permission matrix entries for open, settle, void, reassign, close and reopen, the grace days. */
public record SettingsInput(List<Change> changes) {

    /** A setting the form sets: its key (as the audit names it), its value as the screen shows it (null: blank —
     *  no clerk limit, no cap, a grade on the sheet's terms, the policy date on the sheet's today, the period
     *  numbering off), and whether it is dated, and the from-date given (null: none given — a dated setting is then
     *  recorded from the sheet's today). */
    public record Change(String key, String value, boolean dated, LocalDate from) {
    }

    public boolean sets(String key) {
        return changes.stream().anyMatch(c -> c.key().equals(key));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.orm.ObjectOptimisticLockingFailureException;

/** Saves the person's name and terms, and records their grade from the form's from-date (the sheet's today when blank),
 *  replacing the grade recorded for that date and keeping the others. */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, @Val Sheet sheet, PersonRepository repository,
            PersonGradeRepository grades, EntityManager entityManager)
            throws InvalidPersonException, PersonConflictException {
        if (request.version() == null || request.version() != person.getVersion()) {
            throw new PersonConflictException();
        }
        if (repository.existsBySheetIdAndNameIgnoreCaseAndIdNot(person.getSheetId(), request.name(), person.getId())) {
            throw new InvalidPersonException("The name is already in use on this sheet.");
        }
        LocalDate from = request.gradeFrom() == null || request.gradeFrom().isEmpty() ? sheet.getToday()
                : LocalDate.parse(request.gradeFrom());
        person.setName(request.name());
        person.setTerms(request.termsDays());
        try {
            // Every save raises the version, even one that changes only a dated grade.
            entityManager.lock(person, LockModeType.OPTIMISTIC_FORCE_INCREMENT);
            repository.saveAndFlush(person);
        } catch (ObjectOptimisticLockingFailureException | jakarta.persistence.OptimisticLockException e) {
            // saved by someone else between the load and this save
            throw new PersonConflictException();
        }
        PersonGrade dated = grades.findByPersonIdAndFromDate(person.getId(), from)
                .orElseGet(() -> new PersonGrade(person.getSheetId(), person.getId(), request.grade(), from));
        dated.setGrade(request.grade());
        grades.saveAndFlush(dated);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class BuildPerson {
    public void build(@Val PersonRequest request, @Val Sheet sheet, PersonRepository repository, Out<Person> personOut)
            throws InvalidPersonException {
        if (repository.existsBySheetIdAndNameIgnoreCase(sheet.getId(), request.name())) {
            throw new InvalidPersonException("The name is already in use on this sheet.");
        }
        Person person = new Person(sheet.getId(), request.name(), request.grade());
        person.setTerms(request.termsDays());
        personOut.set(repository.save(person));
    }
}
