import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PersonGradeRepository extends JpaRepository<PersonGrade, Long> {

    /** The sheet's dated grades, by from-date. */
    List<PersonGrade> findBySheetIdOrderByFromDateAsc(String sheetId);

    /** The person's dated grades, by from-date. */
    List<PersonGrade> findByPersonIdOrderByFromDateAsc(Long personId);

    Optional<PersonGrade> findByPersonIdAndFromDate(Long personId, LocalDate fromDate);

    /** The person's grades over time. */
    default PersonGrades gradesOf(Person person) {
        return new PersonGrades(person.getGrade(), findByPersonIdOrderByFromDateAsc(person.getId()));
    }

    /** The grades over time of each person on the sheet, by person id; a person with no dated grade is absent. */
    default Map<Long, List<PersonGrade>> datedOnSheet(String sheetId) {
        return findBySheetIdOrderByFromDateAsc(sheetId).stream()
                .collect(Collectors.groupingBy(PersonGrade::getPersonId));
    }
}
-- A soft-closed period: its due-total and each person's are fixed (as on closing), but claims dated in it can
-- still be added, edited and change status. A claim added while its period is soft-closed is a late entry.
ALTER TABLE period ADD COLUMN soft_closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN late_entry BOOLEAN DEFAULT FALSE NOT NULL;
-- A person's statement: their due-total when it was taken (n/a when there was none) and the sheet's
-- today then. Their count and last one are read from here.
CREATE TABLE statement (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    due_total VARCHAR(30) NOT NULL,
    taken_on DATE NOT NULL
);
CREATE INDEX statement_person ON statement (person_id, id);
-- A claim bound by its person's last statement shows and totals the figure it had then (stated_due;
-- null when it had none, n/a), until the next statement rebinds or unbinds it.
ALTER TABLE claim ADD COLUMN stated BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE claim ADD COLUMN stated_due DECIMAL(19, 2);
-- A person's holds over time: each from a date on, to a date (inclusive; null: open-ended). Their OPEN claims
-- dated within a hold count in no live total, unless a statement binds them; their other claims still count.
-- Replaces the single held flag: a person held before is held from the beginning of time.
CREATE TABLE person_hold (
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date DATE
);
CREATE INDEX person_hold_person ON person_hold (person_id);
INSERT INTO person_hold (person_id, from_date, to_date) SELECT id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

